\begin{tikzpicture}[scale=1.0, rotate=0, 
declare function={ zeq(\x) = 1-\x; 
                 },]

\begin{axis}[
		scale=1,
		clip=false,
		view={110}{30},
		hide axis,
		xmin=0,xmax=1.5,
