	plot[variable=\x, domain=0:1, samples=200] (axis cs:{\x},{\yleft},{zeq(\x)})
 -- plot[variable=\x, domain=1:0, samples=200] (axis cs:{\x},{\yright},{zeq(\x)})
	--cycle;
